import re
from datetime import date

_MONTH_NAMES = [
    ("january", "jan"), ("february", "feb"), ("march", "mar"),
    ("april", "apr"), ("may",), ("june", "jun"),
    ("july", "jul"), ("august", "aug"), ("september", "sep", "sept"),
    ("october", "oct"), ("november", "nov"), ("december", "dec"),
]
_MONTHS = {}
for _i, _names in enumerate(_MONTH_NAMES, start=1):
    for _n in _names:
        _MONTHS[_n] = _i

_WEEKDAY_RE = re.compile(
    r"^(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday"
    r"|mon|tues?|wed|thu|thur|thurs|fri|sat|sun)\.?\s+",
    re.IGNORECASE | re.ASCII,
)

_INVALID = "INVALID"


def _clean(s: str) -> str:
    s = s.strip()
    # Drop ordinal suffixes after a digit: 1st, 2nd, 3rd, 4th
    s = re.sub(r"(?<=\d)(st|nd|rd|th)\b", "", s, flags=re.IGNORECASE)
    s = s.replace(",", " ")
    s = re.sub(r"\s+", " ", s).strip()
    # Drop a leading weekday name (e.g. "Tuesday March 5 2024")
    s = _WEEKDAY_RE.sub("", s, count=1).strip()
    return s


def _to_iso(y: int, m: int, d: int) -> str:
    try:
        return date(y, m, d).isoformat()
    except ValueError:
        return _INVALID


def _month_number(token: str):
    return _MONTHS.get(token.lower().rstrip("."))


def _numeric_ymd(a: str, b: str, y: str) -> str:
    """Interpret a/b/y as day-month-year by default; month-day-year only when that is the sole fit."""
    first, second = int(a), int(b)
    if second > 12 and first <= 12:
        month, day = first, second      # MM/DD/YYYY
    else:
        day, month = first, second      # DD/MM/YYYY (default)
    return _to_iso(int(y), month, day)


def parse(s: str) -> str:
    if not isinstance(s, str):
        return _INVALID

    t = _clean(s)
    if not t:
        return _INVALID

    # YYYY-MM-DD, YYYY/MM/DD, YYYY.MM.DD
    m = re.fullmatch(r"([0-9]{4})[-/.]([0-9]{1,2})[-/.]([0-9]{1,2})", t, re.ASCII)
    if m:
        return _to_iso(int(m.group(1)), int(m.group(2)), int(m.group(3)))

    # YYYYMMDD
    m = re.fullmatch(r"([0-9]{4})([0-9]{2})([0-9]{2})", t, re.ASCII)
    if m:
        return _to_iso(int(m.group(1)), int(m.group(2)), int(m.group(3)))

    # Numeric D/M/Y or M/D/Y with separators -, /, .
    m = re.fullmatch(r"([0-9]{1,2})[-/.]([0-9]{1,2})[-/.]([0-9]{4})", t, re.ASCII)
    if m:
        return _numeric_ymd(m.group(1), m.group(2), m.group(3))

    # 22 Feb 1900 / 22 February 1900
    m = re.fullmatch(r"([0-9]{1,2}) ([A-Za-z]+\.?) ([0-9]{4})", t, re.ASCII)
    if m:
        month = _month_number(m.group(2))
        if month is None:
            return _INVALID
        return _to_iso(int(m.group(3)), month, int(m.group(1)))

    # Feb 22 1900 / February 22 1900
    m = re.fullmatch(r"([A-Za-z]+\.?) ([0-9]{1,2}) ([0-9]{4})", t, re.ASCII)
    if m:
        month = _month_number(m.group(1))
        if month is None:
            return _INVALID
        return _to_iso(int(m.group(3)), month, int(m.group(2)))

    return _INVALID

import re
from datetime import date

_MONTH_NAMES = [
    "january", "february", "march", "april", "may", "june",
    "july", "august", "september", "october", "november", "december",
]
_MONTHS = {}
for _i, _name in enumerate(_MONTH_NAMES, start=1):
    _MONTHS[_name] = _i
    _MONTHS[_name[:3]] = _i
_MONTHS["sept"] = 9

_WEEKDAY_RE = re.compile(
    r"^(monday|tuesday|wednesday|thursday|friday|saturday|sunday|"
    r"mon|tue|tues|wed|thu|thur|thurs|fri|sat|sun)\.?\s+"
)


def _to_iso(year, month, day):
    try:
        return date(year, month, day).isoformat()
    except (ValueError, OverflowError):
        return None


def _month_from_name(token):
    return _MONTHS.get(token.rstrip("."))


def _resolve_numeric(a, b, year):
    # Day-first by default; fall back to month-first only when the
    # first component cannot be a day-of-month candidate in that order.
    if a > 12 and b <= 12:
        return _to_iso(year, b, a)
    if b > 12 and a <= 12:
        return _to_iso(year, a, b)
    # Ambiguous (both <= 12): read as day/month.
    return _to_iso(year, b, a)


def parse(s: str) -> str:
    if not isinstance(s, str):
        return "INVALID"

    t = s.strip().lower()
    t = t.replace(",", " ")
    t = re.sub(r"(\d)(st|nd|rd|th)\b", r"\1", t)
    t = re.sub(r"\s+", " ", t).strip()
    t = _WEEKDAY_RE.sub("", t).strip()

    if not t:
        return "INVALID"

    # 1. ISO-like: YYYY-MM-DD, YYYY/MM/DD, YYYY.MM.DD
    m = re.fullmatch(r"(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})", t)
    if m:
        result = _to_iso(int(m.group(1)), int(m.group(2)), int(m.group(3)))
        return result or "INVALID"

    # 2. Day Month Year: "22 feb 1900", "22 february 1900", "22-feb-1900"
    m = re.fullmatch(r"(\d{1,2})[\s\-/.]+([a-z]+\.?)[\s\-/.]+(\d{4})", t)
    if m:
        month = _month_from_name(m.group(2))
        if month:
            result = _to_iso(int(m.group(3)), month, int(m.group(1)))
            return result or "INVALID"
        return "INVALID"

    # 3. Month Day Year: "feb 22 1900", "february 22 1900"
    m = re.fullmatch(r"([a-z]+\.?)[\s\-/.]+(\d{1,2})[\s\-/.]+(\d{4})", t)
    if m:
        month = _month_from_name(m.group(1))
        if month:
            result = _to_iso(int(m.group(3)), month, int(m.group(2)))
            return result or "INVALID"
        return "INVALID"

    # 4. Numeric with separators: DD/MM/YYYY, MM/DD/YYYY (resolved by value)
    m = re.fullmatch(r"(\d{1,2})[/.\-](\d{1,2})[/.\-](\d{4})", t)
    if m:
        result = _resolve_numeric(int(m.group(1)), int(m.group(2)), int(m.group(3)))
        return result or "INVALID"

    return "INVALID"

import re
from datetime import date

_MONTHS = {
    "january": 1, "february": 2, "march": 3, "april": 4,
    "may": 5, "june": 6, "july": 7, "august": 8,
    "september": 9, "october": 10, "november": 11, "december": 12,
}
# Add three-letter abbreviations and the common "sept" variant.
_MONTHS.update({name[:3]: num for name, num in list(_MONTHS.items())})
_MONTHS["sept"] = 9

# Year-first with a consistent separator: 2016-2-29, 2016/02/29, 2016.2.9
_YMD = re.compile(r"(\d{4})([-/.])(\d{1,2})\2(\d{1,2})", re.ASCII)
# Day-first numeric with a consistent separator: 31/12/1999, 5-3-2024, 05.03.2024
_DMY_NUM = re.compile(r"(\d{1,2})([-/.])(\d{1,2})\2(\d{4})", re.ASCII)
# Compact: 20160229
_COMPACT = re.compile(r"(\d{4})(\d{2})(\d{2})", re.ASCII)
# Day-month-year text: 5th March 2024, 5 mar. 2024, 05 March, 2024
_DMY_TEXT = re.compile(
    r"(\d{1,2})(?:st|nd|rd|th)?\s+([a-z]+)\.?,?\s+(\d{4})", re.ASCII
)
# Month-day-year text: March 5th, 2024, aug 1 1985, Aug. 1, 1985
_MDY_TEXT = re.compile(
    r"([a-z]+)\.?\s+(\d{1,2})(?:st|nd|rd|th)?,?\s+(\d{4})", re.ASCII
)


def _build(year: int, month: int, day: int) -> str:
    try:
        # date() enforces real calendar rules, including leap years
        return date(year, month, day).isoformat()
    except ValueError:
        return "INVALID"


def parse(s: str) -> str:
    if not isinstance(s, str):
        return "INVALID"

    # Trim, collapse internal whitespace, and lowercase for matching.
    t = " ".join(s.split()).lower()
    if not t:
        return "INVALID"

    m = _YMD.fullmatch(t)
    if m:
        return _build(int(m.group(1)), int(m.group(3)), int(m.group(4)))

    # Numeric ambiguous dates are read day-first (DD/MM/YYYY).
    m = _DMY_NUM.fullmatch(t)
    if m:
        return _build(int(m.group(4)), int(m.group(3)), int(m.group(1)))

    m = _COMPACT.fullmatch(t)
    if m:
        return _build(int(m.group(1)), int(m.group(2)), int(m.group(3)))

    m = _DMY_TEXT.fullmatch(t)
    if m:
        month = _MONTHS.get(m.group(2))
        if month is None:
            return "INVALID"
        return _build(int(m.group(3)), month, int(m.group(1)))

    m = _MDY_TEXT.fullmatch(t)
    if m:
        month = _MONTHS.get(m.group(1))
        if month is None:
            return "INVALID"
        return _build(int(m.group(3)), month, int(m.group(2)))

    return "INVALID"
